1556	// computeReachableFromMain returns a set of commit hashes on the main/default branch's first-parent chain.
1557	// On the default branch itself, returns an empty map (no filtering needed).
1558	// Only first-parent commits are included — commits from side branches merged into main are excluded,
1559	// since those could be feature branch commits that shouldn't be filtered out.
1560	func computeReachableFromMain(ctx context.Context, repo *git.Repository) map[plumbing.Hash]bool {
1561		reachableFromMain := make(map[plumbing.Hash]bool)
1562	
1563		isOnDefault, _ := strategy.IsOnDefaultBranch(repo)
1564		if isOnDefault {
1565			return reachableFromMain // No filtering needed on default branch
1566		}
1567	
1568		// Resolve main branch hash
1569		var mainBranchHash plumbing.Hash
1570		if defaultBranchName := strategy.GetDefaultBranchName(repo); defaultBranchName != "" {
1571			ref, refErr := repo.Reference(plumbing.ReferenceName("refs/heads/"+defaultBranchName), true)
1572			if refErr != nil {
1573				ref, refErr = repo.Reference(plumbing.ReferenceName("refs/remotes/origin/"+defaultBranchName), true)
1574			}
1575			if refErr == nil {
1576				mainBranchHash = ref.Hash()
1577			}
1578		}
1579		if mainBranchHash == plumbing.ZeroHash {
1580			mainBranchHash = strategy.GetMainBranchHash(repo)
1581		}
1582		if mainBranchHash == plumbing.ZeroHash {
1583			return reachableFromMain
1584		}
1585	
1586		// Walk main's first-parent chain to build the set
1587		_ = walkFirstParentCommits(ctx, repo, mainBranchHash, strategy.MaxCommitTraversalDepth, func(c *object.Commit) error { //nolint:errcheck // Best-effort
1588			reachableFromMain[c.Hash] = true
1589			return nil
1590		})
1591	
1592		return reachableFromMain
1593	}
