1597	// This avoids the full DAG traversal that repo.Log() does, which follows ALL parents
1598	// of merge commits and can walk into unrelated branch history (e.g., main's full
1599	// history after merging main into a feature branch).
1600	func walkFirstParentCommits(ctx context.Context, repo *git.Repository, from plumbing.Hash, limit int, fn func(*object.Commit) error) error {
1601		current, err := repo.CommitObject(from)
1602		if err != nil {
1603			return fmt.Errorf("failed to get commit %s: %w", from, err)
1604		}
1605	
1606		for count := 0; limit <= 0 || count < limit; count++ {
1607			if err := ctx.Err(); err != nil {
1608				return err //nolint:wrapcheck // Propagating context cancellation
1609			}
1610			if err := fn(current); err != nil {
1611				if errors.Is(err, errStopIteration) {
