package cli

import (
	"fmt"
	"sync"

	"github.com/spf13/cobra"
)

// aliasOptions configures aliasOf behavior.
type aliasOptions struct {
	hidden       bool
	deprecation  string // when set, prints once-per-process stderr warning and replaces Use with the deprecation hint
	overrideUse  string
	parentOfNew  string // for deprecation message: e.g. "agent" when configure aliases the agent group
	keepRunESame bool
}

// AliasOption mutates aliasOptions.
type AliasOption func(*aliasOptions)

// WithHidden hides the alias from `--help`.
func WithHidden() AliasOption { return func(o *aliasOptions) { o.hidden = true } }

// WithDeprecation marks the alias as deprecated and prints a one-time stderr
