323	func runExplain(ctx context.Context, w, errW io.Writer, sessionID, commitRef, checkpointID, target string, noPager, verbose, full, rawTranscript, generate, force, searchAll bool) error {
324		// Count mutually exclusive flags (--commit and --checkpoint are mutually exclusive)
325		// --session is now a filter for the list view, not a separate mode
326		flagCount := 0
327		if commitRef != "" {
328			flagCount++
329		}
330		if checkpointID != "" {
331			flagCount++
332		}
333		// If --session is combined with --commit or --checkpoint, that's still an error
334		if sessionID != "" && flagCount > 0 {
335			return errors.New("cannot specify multiple of --session, --commit, --checkpoint")
336		}
337		if flagCount > 1 {
338			return errors.New("cannot specify multiple of --session, --commit, --checkpoint")
339		}
340	
341		// Route to appropriate handler
342		if target != "" {
343			return runExplainAuto(ctx, w, errW, target, noPager, verbose, full, rawTranscript, generate, force, searchAll)
344		}
345		if commitRef != "" {
346			return runExplainCommit(ctx, w, errW, commitRef, noPager, verbose, full, rawTranscript, generate, force, searchAll)
347		}
348		if checkpointID != "" {
349			return runExplainCheckpoint(ctx, w, errW, checkpointID, noPager, verbose, full, rawTranscript, generate, force, searchAll)
350		}
351	
352		// Default or with session filter: show list view (optionally filtered by session)
353		return runExplainBranchWithFilter(ctx, w, noPager, sessionID)
354	}
355	
356	// runExplainAuto resolves a positional target as either a checkpoint ID
357	// (or prefix) or a git commit ref. Ordering: checkpoint path first (which
358	// also handles shadow-branch temp checkpoints), falling back to commit
359	// resolution only on checkpoint.ErrCheckpointNotFound. --generate runs
360	// an ambiguity pre-check to avoid writing a summary to the wrong
361	// checkpoint on short-prefix collisions.
362	func runExplainAuto(ctx context.Context, w, errW io.Writer, target string, noPager, verbose, full, rawTranscript, generate, force, searchAll bool) error {
363		lookup, lookupErr := newExplainCheckpointLookup(ctx, nil)
364		if generate {
365			if err := runExplainAutoAmbiguityGuard(ctx, target, lookup, lookupErr); err != nil {
366				return err
367			}
368		}
369		checkpointErr := runExplainCheckpointWithLookup(ctx, w, errW, target, noPager, verbose, full, rawTranscript, generate, force, searchAll, lookup, lookupErr)

