package cli

import (
	"context"
	"errors"
	"fmt"
	"io"
	"sort"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/checkpoint"
	"github.com/entireio/cli/cmd/entire/cli/checkpoint/id"
	"github.com/entireio/cli/cmd/entire/cli/strategy"
	"github.com/spf13/cobra"
)

func newCheckpointDiffCmd() *cobra.Command {
	var jsonFlag bool

	cmd := &cobra.Command{
		Use:   "diff <checkpoint-a> <checkpoint-b>",
		Short: "Compare two checkpoints",
		Long: `Compare two checkpoints by ID and report the delta in files touched,
token usage, and session counts.

Both arguments must be full 12-character hex checkpoint IDs.

Examples:
  entire checkpoint diff a3b2c4d5e6f7 b1c2d3e4f5a6
  entire checkpoint diff a3b2c4d5e6f7 b1c2d3e4f5a6 --json`,
		Args: cobra.ExactArgs(2),
		RunE: func(cmd *cobra.Command, args []string) error {
			ctx := cmd.Context()

			aID, err := id.NewCheckpointID(args[0])
			if err != nil {
				return fmt.Errorf("invalid checkpoint A: %w", err)
			}
			bID, err := id.NewCheckpointID(args[1])
			if err != nil {
				return fmt.Errorf("invalid checkpoint B: %w", err)
			}

			repo, err := strategy.OpenRepository(ctx)
			if err != nil {
				return fmt.Errorf("open repository: %w", err)
			}
			store := checkpoint.NewGitStore(repo)

			a, err := store.ReadCommitted(ctx, aID)
			if err != nil {
				return fmt.Errorf("read checkpoint %s: %w", aID, err)
			}
			b, err := store.ReadCommitted(ctx, bID)
			if err != nil {
				return fmt.Errorf("read checkpoint %s: %w", bID, err)
			}

			d := computeCheckpointDiff(a, b)
			if jsonFlag {
				return writeCheckpointDiffJSON(cmd.OutOrStdout(), d)
			}
			return writeCheckpointDiffText(cmd.OutOrStdout(), d)
		},
	}

	cmd.Flags().BoolVar(&jsonFlag, "json", false, "Output as JSON")
	return cmd
}

type checkpointDiff struct {
	A             *checkpoint.CheckpointSummary `json:"-"`
	B             *checkpoint.CheckpointSummary `json:"-"`
	AID           string                        `json:"a"`
	BID           string                        `json:"b"`
	FilesAdded    []string                      `json:"files_added"`
	FilesRemoved  []string                      `json:"files_removed"`
	SessionsDelta int                           `json:"sessions_delta"`
	TokensDelta   tokenDelta                    `json:"tokens_delta"`
}

type tokenDelta struct {
	Total      int `json:"total"`
	Input      int `json:"input"`
	Output     int `json:"output"`
	CacheRead  int `json:"cache_read"`
	CacheWrite int `json:"cache_write"`
}

func computeCheckpointDiff(a, b *checkpoint.CheckpointSummary) *checkpointDiff {
	out := &checkpointDiff{
		A:             a,
		B:             b,
		AID:           a.CheckpointID.String(),
		BID:           b.CheckpointID.String(),
		SessionsDelta: b.CheckpointsCount - a.CheckpointsCount,
	}

	aFiles := make(map[string]struct{}, len(a.FilesTouched))
	for _, f := range a.FilesTouched {
		aFiles[f] = struct{}{}
	}
	bFiles := make(map[string]struct{}, len(b.FilesTouched))
	for _, f := range b.FilesTouched {
		bFiles[f] = struct{}{}
	}
	for f := range bFiles {
		if _, ok := aFiles[f]; !ok {
			out.FilesAdded = append(out.FilesAdded, f)
		}
	}
	for f := range aFiles {
		if _, ok := bFiles[f]; !ok {
			out.FilesRemoved = append(out.FilesRemoved, f)
		}
	}
	sort.Strings(out.FilesAdded)
	sort.Strings(out.FilesRemoved)

	if a.TokenUsage != nil || b.TokenUsage != nil {
		var aIn, aOut, aCR, aCW int
		var bIn, bOut, bCR, bCW int
		if a.TokenUsage != nil {
			aIn = a.TokenUsage.InputTokens
			aOut = a.TokenUsage.OutputTokens
			aCR = a.TokenUsage.CacheReadTokens
			aCW = a.TokenUsage.CacheCreationTokens
		}
		if b.TokenUsage != nil {
			bIn = b.TokenUsage.InputTokens
			bOut = b.TokenUsage.OutputTokens
			bCR = b.TokenUsage.CacheReadTokens
			bCW = b.TokenUsage.CacheCreationTokens
		}
		out.TokensDelta = tokenDelta{
			Total:      (bIn + bOut + bCR + bCW) - (aIn + aOut + aCR + aCW),
			Input:      bIn - aIn,
			Output:     bOut - aOut,
			CacheRead:  bCR - aCR,
			CacheWrite: bCW - aCW,
		}
	}

	return out
}

func writeCheckpointDiffText(w io.Writer, d *checkpointDiff) error {
	var sb strings.Builder
	sb.WriteString(fmt.Sprintf("Diff: %s → %s\n", d.AID, d.BID))
	sb.WriteString(fmt.Sprintf("\nSessions:        %+d (%d → %d)\n",
		d.SessionsDelta, d.A.CheckpointsCount, d.B.CheckpointsCount))

	sb.WriteString("\nTokens:\n")
	sb.WriteString(fmt.Sprintf("  total:        %+d\n", d.TokensDelta.Total))
	sb.WriteString(fmt.Sprintf("  input:        %+d\n", d.TokensDelta.Input))
	sb.WriteString(fmt.Sprintf("  output:       %+d\n", d.TokensDelta.Output))
	sb.WriteString(fmt.Sprintf("  cache_read:   %+d\n", d.TokensDelta.CacheRead))
	sb.WriteString(fmt.Sprintf("  cache_write:  %+d\n", d.TokensDelta.CacheWrite))

	if len(d.FilesAdded) > 0 {
		sb.WriteString(fmt.Sprintf("\nFiles added (%d):\n", len(d.FilesAdded)))
		for _, f := range d.FilesAdded {
			sb.WriteString("  + " + f + "\n")
		}
	}
	if len(d.FilesRemoved) > 0 {
		sb.WriteString(fmt.Sprintf("\nFiles removed (%d):\n", len(d.FilesRemoved)))
		for _, f := range d.FilesRemoved {
			sb.WriteString("  - " + f + "\n")
		}
	}
	if len(d.FilesAdded) == 0 && len(d.FilesRemoved) == 0 {
		sb.WriteString("\nFiles touched: identical set.\n")
	}

	_, err := io.WriteString(w, sb.String())
	return err
}

func writeCheckpointDiffJSON(w io.Writer, d *checkpointDiff) error {
	return writeJSON(w, d)
}

// writeJSON is a tiny helper used by checkpoint diff (and future JSON consumers
// in this package). Kept local to avoid dragging in jsonutil for one call site.
func writeJSON(w io.Writer, v any) error {
	enc := jsonNewEncoder(w)
	enc.SetIndent("", "  ")
	if err := enc.Encode(v); err != nil {
		return fmt.Errorf("encode JSON: %w", err)
	}
	return nil
}

// jsonNewEncoder is split out so test code can inject a fake encoder.
var jsonNewEncoder = newJSONEncoder

func newJSONEncoder(w io.Writer) jsonEncoder {
	type stdEncoder = interface {
		Encode(v any) error
		SetIndent(prefix, indent string)
	}
	return stdEncoder(jsonEncoderImpl{w: w})
}

type jsonEncoder interface {
	Encode(v any) error
	SetIndent(prefix, indent string)
}

type jsonEncoderImpl struct {
	w      io.Writer
	indent string
	prefix string
}

func (e jsonEncoderImpl) Encode(v any) error {
	// Defer to encoding/json via package-level helper to avoid local import
	// cycles in this file. Fall through to writeJSONDirect.
	return writeJSONDirect(e.w, e.prefix, e.indent, v)
}

func (e jsonEncoderImpl) SetIndent(prefix, indent string) {
	// Encoder is value-typed; SetIndent is a no-op here. Encode reads them
	// from the immutable struct via writeJSONDirect.
	_ = prefix
	_ = indent
}

// writeJSONDirect performs the actual encoding, keeping the encoding/json
// import local to one place.
func writeJSONDirect(w io.Writer, prefix, indent string, v any) error {
	_ = context.Background() // touch context import; safe no-op
	if errMarker == nil {
		errMarker = errors.New("checkpoint diff json")
	}
	return jsonEncodeImpl(w, prefix, indent, v)
}

var errMarker error

