// aliasOptions configures aliasOf behavior.
type aliasOptions struct {
	hidden      bool
	deprecation string // when set, marks the alias as deprecated and prints once-per-process stderr warning
	overrideUse string
}

// AliasOption mutates aliasOptions.
type AliasOption func(*aliasOptions)

// WithHidden hides the alias from `--help`.
func WithHidden() AliasOption { return func(o *aliasOptions) { o.hidden = true } }

// WithDeprecation marks the alias as deprecated and prints a one-time stderr
// warning the first time it is used in a process. The replacement string is
// shown verbatim, e.g. "entire agent" or "entire clean --shadow".
func WithDeprecation(replacement string) AliasOption {
	return func(o *aliasOptions) { o.deprecation = replacement }
}

// WithUse overrides the alias's Use string (default: child.Use).
func WithUse(use string) AliasOption {
	return func(o *aliasOptions) { o.overrideUse = use }
}

// aliasOf returns a top-level Cobra command that delegates to the given child's
// RunE/Run, args, and PreRunE/PostRunE hooks. It also copies the child's flag
// set so flag parsing matches exactly. The child is unchanged.
func aliasOf(child *cobra.Command, opts ...AliasOption) *cobra.Command {
	options := aliasOptions{}
	for _, opt := range opts {
		opt(&options)
	}

	use := child.Use
	if options.overrideUse != "" {
		use = options.overrideUse
	}

	alias := &cobra.Command{
		Use:                use,
		Short:              child.Short,
		Long:               child.Long,
		Args:               child.Args,
		ValidArgsFunction:  child.ValidArgsFunction,
		PersistentPreRunE:  child.PersistentPreRunE,
		PreRunE:            child.PreRunE,
		PostRunE:           child.PostRunE,
		PersistentPostRunE: child.PersistentPostRunE,
		Hidden:             options.hidden,
		SilenceUsage:       child.SilenceUsage,
		SilenceErrors:      child.SilenceErrors,
		DisableFlagParsing: child.DisableFlagParsing,
	}

	if options.deprecation != "" {
		alias.Deprecated = fmt.Sprintf("use '%s' instead", options.deprecation)
	}

	if child.RunE != nil {
		runE := child.RunE
		alias.RunE = func(cmd *cobra.Command, args []string) error {
			if options.deprecation != "" {
				warnDeprecatedAliasOnce(cmd, use, options.deprecation)
			}
			return runE(cmd, args)
		}
	} else if child.Run != nil {
		run := child.Run
		alias.Run = func(cmd *cobra.Command, args []string) {
			if options.deprecation != "" {
				warnDeprecatedAliasOnce(cmd, use, options.deprecation)
			}
			run(cmd, args)
		}
	}

	// Copy child flags into alias flag set so flag parsing matches.
	child.Flags().VisitAll(func(f *pflag.Flag) {
		alias.Flags().AddFlag(f)
	})

	return alias
}

var deprecationWarnOnce sync.Map // key: deprecation key, value: *sync.Once

func warnDeprecatedAliasOnce(cmd *cobra.Command, oldUse, replacement string) {
	old := firstWord(oldUse)
	if old == "" {
		old = cmd.Name()
	}
	key := old + "->" + replacement
	once, _ := deprecationWarnOnce.LoadOrStore(key, &sync.Once{})
	once.(*sync.Once).Do(func() {
		fmt.Fprintf(cmd.ErrOrStderr(), "Warning: 'entire %s' is deprecated; use 'entire %s' instead.\n", old, replacement)
	})
}

func firstWord(s string) string {
	for i := range len(s) {
		if s[i] == ' ' || s[i] == '\t' {
			return s[:i]
		}
	}
	return s
}

